def review_directives(session: GameSession) -> str:
    """诏书草案审阅界面。返回 'issue' | 'back' | 'skip'。"""
    session.enter_review()
    while True:
        directives = session.list_directives(include_pending=True)
        pending = [d for d in directives if d.status == "pending"]
        drafts = [d for d in directives if d.status == "draft"]
        staged_directives = [
            p for p in session.db.list_pending_actions(session.state.turn)
            if p.get("kind") == "directive"
        ]
        print(f"\n本{TURN_UNIT}诏书草案：")
        if pending:
            print(f"  · {len(pending)} 道历史拟旨候结束回合成案：")
            for d in pending:
                print(f"  [待核定] #{d.id}  {wrap(d.text)}")
        if staged_directives:
            print(f"  · {len(staged_directives)} 道对话拟旨待颁诏默认同意。")
        if drafts:
            for idx, d in enumerate(drafts, 1):
                print(f"{idx}. #{d.id}")
                print(f"   {wrap(d.text)}")
        elif not pending and not staged_directives:
            print("（暂无指令。back 继续召见，或 add 新增。）")
        print("\n操作：issue 结束回合 | back 继续召见 | add 新增 | edit N 改 | del N 删 | exit 退出")
        raw = input("诏书草案> ").strip()
        if not raw:
            continue
        lowered = raw.lower()
        if lowered in EXIT_COMMANDS:
            raise ExitGame
        if lowered in COURT_BREAK_COMMANDS:
            if drafts or pending or staged_directives:
                print(f"本{TURN_UNIT}尚有候选旨意；退朝将按结束回合规则成案。请输入 issue。")
                continue
            return "skip"
        if lowered in {"back", "b", "返回", "继续召见"}:
            from ming_sim.session import FRONT_HALF_DONE_PHASES
            if session.state.turn_phase in FRONT_HALF_DONE_PHASES:
                # 粘滞相位下 back 是静默 no-op，play_turn 会立刻把人弹回本菜单——
                # 给一行提示，别让玩家以为按键失灵（ship-pre r6）。
                print("\n上月结算未完成，无法继续召见；请输入 issue 续跑结算。")
                continue
            session.back_to_summoning()
            return "back"
        if lowered in {"issue", "颁布", "颁布诏书", "发布", "拟诏"}:
            from ming_sim.session import FRONT_HALF_DONE_PHASES
            if session.state.turn_phase in FRONT_HALF_DONE_PHASES:
                # 恢复态：上月结算未完成（崩溃/中止后），跳过拟诏直接续跑结算——
                # resolve_turn 的恢复分流自己决定重放/重新推演/回放决策点
                # （ship-pre r3：write_decree 在此态必拒，不开此口 CLI 永远够不到恢复入口）。
                print("\n检测到上月结算未完成，续跑结算……")
                return "issue"
            return "issue"
        # 变更器统一接 ValueError（FRONT_HALF_DONE 冻结期的指引消息）：打印后留在
        # 审阅循环，不崩出进程（ship-pre r2，与 write_decree 既有 try 同款）。
        try:
            if lowered == "add" or raw == "新增":
                text = input("指令内容：")
                if text.strip():
                    from ming_sim.cli_backend import capture_manual_directive_payload
                    dv = session.add_directive(
                        text,
                        dossier_payload=capture_manual_directive_payload(
                            text, session.llm_config,
                            **({"db": session.db, "content": session.content}
                               if getattr(session, "content", None) is not None else {}),
                        ),
                    )
                    print(f"已新增草案 #{dv.id}。")
                else:
                    print("指令为空，已取消。")
                continue
            parts = raw.split(maxsplit=1)
            verb = parts[0].lower()
            if len(parts) == 2 and parts[1].lstrip("#").isdigit():
                target_id = int(parts[1].lstrip("#"))
                if verb in {"edit", "改", "修改"}:
                    if not any(d.id == target_id for d in drafts):
                        print("没有这条草案。")

def run_tick(name, st, p, actions, expect=None):
    print(f"\n{'='*64}\n{name}\n{'='*64}")
    for rq in ('三饷应征','火耗率','逋赋率','起运定额','Due'):   # 必填参数 presence 检查(gemini R2:原缺失走 KeyError;
        if rq not in p: raise ValueError(f"param {rq} 缺失")      # 不给默认0——火耗率缺省成0=静默改经济学,fail-loud)
    for sk in (*CASH_KEYS, *CLAIM_KEYS, '官民田', '隐田'):       # 开账显式 None 前置拦(gemini R2:float(None) TypeError 早于守门)
        if sk in st and st[sk] is None: raise ValueError(f"开账 stock {sk} 为 None")
    cash = {k: float(st.get(k,0)) for k in CASH_KEYS}
    claim = {k: float(st.get(k,0)) for k in CLAIM_KEYS}
    官民田 = float(st.get('官民田',0)); 隐田 = float(st.get('隐田',0))
    地0 = 官民田 + 隐田                                  # 土地守恒锚:清丈只重分类,总亩数不变
    cash0 = sum(cash.values()); C0 = {k: cash[k] for k in CASH_KEYS if k.startswith('C_')}
    claim0 = dict(claim)
    cash_in = cash_out = 0.0
    r = dict(实征=0,火耗实收=0,清欠=0,拨付gross=0,起运到京=0,实付=0,偿旧欠=0,行政补饷=0,
             漂没=0,中饱=0,民欠新增=0,蠲免=0,unmet_relief=0,
             NewDebt={'军饷欠':0,'官俸欠':0,'宗禄欠':0},Repaid={'军饷欠':0,'官俸欠':0,'宗禄欠':0},
             action还={'军饷欠':0})

    def xfer_internal(frm, to, amount, eff=1.0):
        """CASH 内部 3-way 转移:source减=target增+C_eff损耗增。frm/to 均 CASH。"""
        actual = min(amount, cash[frm]); cash[frm] -= actual
        got = actual*eff; loss = actual*(1-eff)
        cash[to] += got
        if loss > 0: cash['C_eff损耗'] += loss
        return actual

    # ── ⓪ action phase:先收集→算 k→按 k 执行(transfer 此时执行)──
    for a in actions:                                   # 输入校验 fail-loud(codex r16 / Fable:NaN/inf + 0-cost清丈)
        if 'type' not in a: raise ValueError(f"action 缺 type: {a}")
        for nf in ('cost','amount','挖隐田','eff'):      # NaN/inf/非数值 入口拦截(nan<0=False、str 比较 TypeError 均穿守门)
            v = a.get(nf)
            if v is None: continue
            if isinstance(v, bool) or not isinstance(v, (int, float)): raise ValueError(f"{nf} 非数值: {a}")
            if not math.isfinite(float(v)): raise ValueError(f"{nf} 非有限值(NaN/inf): {a}")
        if a['type'] not in KNOWN_ACTIONS: raise ValueError(f"unknown action: {a['type']}")
        if a.get('cost',0) < 0 or a.get('amount',0) < 0 or a.get('挖隐田',0) < 0: raise ValueError(f"负 cost/amount/挖隐田: {a}")
        if not (0 <= a.get('eff',1.0) <= 1): raise ValueError(f"eff 越界: {a}")
        if a['type'] == '补饷' and a.get('amount',0) != 0: raise ValueError(f"补饷不接受 amount(cost即支付): {a}")
        if a['type'] in ('清欠','蠲免','追赃','挪借火耗') and a.get('cost',0) != 0:
            raise ValueError(f"{a['type']} 禁带 cost(征收/转移类按 §9,否则幽灵预算压 k): {a}")
        if a['type'] in ('清丈','营建') and a.get('cost',0) <= 0:    # 行政成本类必须 cost>0(否则免费抬税基=违P3爽感)
            raise ValueError(f"{a['type']} 必须 cost>0(行政成本类): {a}")
    for rk in ('火耗率','逋赋率','漂没率','中饱率'):
        rv = p.get(rk, 0)                                # 字符串/bool 率值原在比较处 TypeError(gemini R3);bool 是 int 子类须显式拒
        if isinstance(rv, bool) or not isinstance(rv, (int, float)): raise ValueError(f"{rk} 非数值")
        if not (0 <= rv <= 1): raise ValueError(f"{rk} 越界")
    for pk in ('正赋应征','三饷应征','起运定额','拨付gross','正赋亩额'):  # param 量纲负/非有限 fail-loud(r21/opus 负值;ship-adv NaN/inf 同拦)
        v = p.get(pk)
        if v is not None:
            if isinstance(v, bool) or not isinstance(v, (int, float)): raise ValueError(f"param {pk} 非数值")
            if not math.isfinite(float(v)): raise ValueError(f"param {pk} 非有限值(NaN/inf)")
            if v < 0: raise ValueError(f"param {pk} 为负")
        elif pk in p and pk != '正赋应征':                  # 仅 正赋应征 可 None=走亩额派生;其余显式 None 拒(防 TypeError 半程崩)
            raise ValueError(f"param {pk} 为 None(仅 正赋应征 可 None)")
    for hk,dv in p.get('Due',{}).items():               # NaN Due→min(Pool,nan)=Pool 整池付给 NaN 且五层全过(ship-adv 实测)
        if hk not in ('军饷','官俸','宗禄','赈济'):       # 拼错科目=settlement+oracle 一致 .get 忽略→法定支出静默蒸发(codex r2)
            raise ValueError(f"Due 含未知科目 {hk}")
        if isinstance(dv, bool) or not isinstance(dv, (int, float)): raise ValueError(f"Due[{hk}] 非数值")
        if not math.isfinite(float(dv)): raise ValueError(f"Due[{hk}] 非有限值(NaN/inf)")
        if dv < 0: raise ValueError(f"Due[{hk}] 为负")
    for sk in (*CASH_KEYS, *CLAIM_KEYS, '官民田', '隐田'):   # CLAIM 也拦(codex r4:负军饷欠→偿还环 rep<0 凭空生钱);非有限同拦
        _sraw = st.get(sk, 0)
        if isinstance(_sraw, bool) or not isinstance(_sraw, (int, float)): raise ValueError(f"开账 stock {sk} 非数值")
        sv = float(_sraw)
        if not math.isfinite(sv): raise ValueError(f"开账 stock {sk} 非有限值(NaN/inf)")
        if sv < 0: raise ValueError(f"开账 stock {sk} 为负")
    Stock_start = cash['省库库银']
    ΣCost = sum(a.get('cost',0) for a in actions if a.get('cost',0) > 0)
    k = 1.0 if (ΣCost == 0 or ΣCost <= Stock_start) else Stock_start/ΣCost
    print(f"⓪ Stock_start={Stock_start:.2f} ΣCost={ΣCost:.2f} k={k:.4f}")
    for a in actions:
        has_cost = a.get('cost',0) > 0
        ec = a.get('cost',0)*k
        amt = a.get('amount',0) * (k if has_cost else 1.0)   # 0-cost action 不缩(spec §6)
        t = a['type']
        if t in ('补饷',):                       # 现金支付补军饷欠(clamp 不超还)
            还 = min(ec, claim['军饷欠']); cash['省库库银'] -= 还; cash_out += 还; r['行政补饷'] += 还
            claim['军饷欠'] -= 还; r['action还']['军饷欠'] += 还
            print(f"  补饷 ec={ec:.2f} 实还={还:.2f}(余{ec-还:.2f}不花)")
        elif t in ('清丈','营建'):                # 行政成本→受款方(吏/工),带 effect

  const modelName = (advanced || primaryModel).toLowerCase();
  if (effectiveBase.includes("deepseek.com")) return false;
  return (
    modelName.startsWith("o1") ||
    modelName.startsWith("o3") ||
    modelName.startsWith("o4") ||
    modelName.startsWith("gpt-5") ||
    effectiveBase.includes("dashscope") ||
    effectiveBase.includes("aliyuncs") ||
    effectiveBase.includes("minimaxi.com") ||
    effectiveBase.includes("minimax.io")
  );
}

def assert_action_candidate_shape(obj: Any) -> Dict[str, Any]:
    ok, reason = validate_action_candidate_shape(obj)
    if not ok:
        raise ActionCandidateShapeError(reason)
    kind = _resolve_kind(obj)
    out = _blank_candidate(kind=kind)

    def _enum(value: object, allowed: FrozenSet[str], default: str) -> str:
        v = str(value if value is not None else default).strip()
        if not v:
            return default
        if v in allowed:
            return v
        raise ActionCandidateShapeError(f"value {v!r} not in {sorted(allowed)}")

    for name, spec in _field_specs().items():
        raw = _field_raw(obj, spec)
        if raw is None:
            raw = spec.default
        # #658：可选正整数 id（as_int + default None）禁 generic clamp；raw 直达严格写边界
        if spec.as_int and spec.default is None:
            out[name] = _field_raw(obj, spec)
            continue
        if spec.as_int:
            out[name] = _as_int(raw, lo=int(spec.int_lo), hi=int(spec.int_hi))
        elif spec.allowed is not None:
            out[name] = _enum(raw, spec.allowed, str(spec.default))
        else:
            # 容器值须 JSON 运输（stages/stop_condition/ongoing_effects 等）；
            # str(list/dict) 是 Python repr（单引号），下游 json.loads 会当坏形丢掉。
            if isinstance(raw, (dict, list, tuple)):
                s = json.dumps(raw, ensure_ascii=False, separators=(",", ":"))
            else:
                # Canonical generated body is transport, not user-entered metadata:
                # preserve the extractor's bytes (including edge whitespace).
                s = str(raw or "")
            if spec.max_len is not None:
                s = s[: spec.max_len]
            out[name] = s
    if "draft_text" in obj:
        out["draft_text"] = obj.get("draft_text")
    # #1509：confirmation 目标编号非 FieldSpec，须随 candidate 过缝。
    if "target_ids" in obj and obj.get("target_ids") is not None:
        out["target_ids"] = obj.get("target_ids")
    elif "目标编号" in obj and obj.get("目标编号") is not None:
        out["target_ids"] = obj.get("目标编号")
    # #1783+#1778：仅 grant 一件事一案可带承办人/名单过缝（assignment 承办人走后置抽取，
    # assignee 不得当改派入口——见 test_assignment_lead_from_extract_*）。
    if kind == "grant_allocation":
        for key in ("assignee", "assignee_id", "assignee_name", "participant_roster", "承办人"):
            if key in obj and obj.get(key) not in (None, ""):
                out[key if key != "承办人" else "assignee"] = obj.get(key)
    return out

def project_draft_extract_to_directive_payload(
    captured: Mapping[str, Any],
    *,
    decree_text: str = "",
    existing_mode: object = None,
    db: Any = None,
    content: Any = None,
) -> Dict[str, object]:
    """把 extract_draft_intent 结果投影为 turn_directives.dossier_payload（与手工 capture 同形）。"""
    declared_mode = resolve_directive_mode(
        extracted=captured.get("mode"), existing=existing_mode,
    )
    if captured.get("draft_action") != "拟旨":
        return _manual_special_decree_payload(declared_mode)
    payload: Dict[str, object] = {
        "dossier_action_type": captured.get("dossier_action_type"),
        "target_kind": captured.get("target_kind"),
        "target_id": captured.get("target_id"),
        "mode": declared_mode,
    }
    for field in (
        "amount", "account", "execution_surface", "assignee",
        "deadline_months", "participant_roster", "locality_scope", "entries",
        "target_dossier_id", "affair_declaration",
        "grant_action", "purpose", "cadence",
        "region_id", "transaction_category",
    ):
        if captured.get(field) not in (None, ""):
            payload[field] = captured[field]
    if (
        payload.get("dossier_action_type") == "grant_allocation"
        and payload.get("grant_action") == "协饷"
    ):
        xiexang_kwargs = dict(
            amount=payload.get("amount"),
            account=str(payload.get("account") or ""),
            purpose=str(payload.get("purpose") or ""),
            target_kind=str(payload.get("target_kind") or ""),
            target_id=str(payload.get("target_id") or ""),
            cadence=str(payload.get("cadence") or ""),
        )
        if db is not None:
            from ming_sim.action_materialize import require_materializable_xiexang_payload
            material = require_materializable_xiexang_payload(
                db, text=str(decree_text or ""), **xiexang_kwargs,
            )
            payload.update({k: v for k, v in material.items() if k != "text"})
        else:
            from ming_sim.action_materialize import require_explicit_xiexang_fields
            payload.update(require_explicit_xiexang_fields(**xiexang_kwargs))
    if payload.get("dossier_action_type") == "dismiss_assignment":
        payload["name"] = str(payload.get("target_id") or "").strip()
        payload["_office_action"] = "罢免"
    from ming_sim.db import (
        classify_directive_structured_kind,
        imperial_push_target_dossier_id,
    )
    # #1849：互斥违规（push 与 triad 并存）此前先被 except 洗成 "ordinary" 再走
    # 组装，报出的可能已是别的字段错；禁临时改判，直接响亮上抛（同一 classify
    # 在下方组装后还会再判一次，掩盖只会让真因被别的字段错顶替）。
    pre_kind = classify_directive_structured_kind(payload)
    if pre_kind not in {"push", "empty"} and payload.get("target_kind") not in (None, ""):
        regions_content = getattr(content, "regions", None) if content is not None else None
        conn = getattr(db, "conn", None) if db is not None else None
        assembled = assemble_structured_decree(
            payload,
            conn=conn,
            regions_content=regions_content,
            validate=True,
        )
        apply_assembled_to_payload(payload, assembled)
    kind = classify_directive_structured_kind(payload)
    if kind == "push":
        push_id = imperial_push_target_dossier_id(payload)
        assert push_id is not None
        push_payload: Dict[str, object] = {
            "target_dossier_id": push_id,
            "mode": declared_mode,
        }
        declaration = captured.get("affair_declaration")

def create_chat_model(
    llm_config: LLMConfig,
    temperature: float = 0.7,
    enable_thinking: bool = False,
    thinking_budget: Optional[int] = None,
    top_p: Optional[float] = None,
    force_json_output: bool = False,
) -> OpenAIChat:
    install_token_stats_patch()
    reasoning_strength = (getattr(llm_config, "reasoning_strength", "") or "").strip().lower()
    extra_body = provider_extra_body(llm_config.base_url, llm_config.model)
    wants_thinking = enable_thinking or reasoning_strength in {"low", "medium", "high"}
    disables_thinking = reasoning_strength == "off"
    # #1797 v7 1b：DeepSeek 系统一关闭压过 reasoning_strength / enable_thinking，
    # 保留 provider_extra_body 的端点关闭键；非 DeepSeek 仍走既有强度语义。
    if not is_deepseek_model(llm_config.model):
        if is_dashscope_base_url(llm_config.base_url) and (wants_thinking or disables_thinking):
            # 推演/评估类 agent 需要深思,开 qwen thinking
            extra_body = {"enable_thinking": not disables_thinking}
            budget = _THINKING_BUDGET_BY_STRENGTH.get(reasoning_strength)
            if budget is not None:
                extra_body["thinking_budget"] = budget
            elif thinking_budget is not None and not disables_thinking:
                extra_body["thinking_budget"] = int(thinking_budget)
        elif is_minimax_base_url(llm_config.base_url) and (wants_thinking or disables_thinking):
            # 统一推理强度优先：off→disabled、低/中/高→adaptive。仅在没有统一强度（遗留
            # enable_thinking 路）时才看旧 thinking_level，否则遗留 thinking_level=disabled 会作
            # 隐藏旋钮把用户选的「中/高」压回 disabled（#358 cmr）。
            if disables_thinking:
                thinking_type = "disabled"
            elif reasoning_strength in {"low", "medium", "high"}:
                thinking_type = "adaptive"
            else:
                thinking_type = (llm_config.thinking_level or "adaptive").strip().lower()
                if thinking_type not in {"adaptive", "disabled"}:
                    thinking_type = "adaptive"
            extra_body = {"thinking": {"type": thinking_type}, "reasoning_split": True}
    # #1465：create_chat_model 默认仍 timeout_seconds / max_retries=1。
    # 已迁移接缝（召对流、run_agent_text）用 bind_transport_sdk_budget 临时覆盖
    # （timeout←attempt_timeout + max_retries=0）。
    # 禁止在 create_chat_model 全局套 transport（CLI runner 等未迁移路径）。
    kwargs: Dict[str, object] = {
        "id": llm_config.model,
        "api_key": llm_config.api_key,
        "base_url": llm_config.base_url,
        "temperature": temperature,
        "timeout": llm_config.timeout_seconds,
        "max_retries": 1,
        "role_map": {"system": "system", "user": "user", "assistant": "assistant", "tool": "tool"},
        "extra_body": extra_body,
    }
    # #1794：API 附加请求头表整张透传 default_headers；空表不塞键＝现状。
    # 不解析、不校验、不按 base_url/模型分派、不内置任何 provider 专用头。
    headers = llm_config.default_headers or {}
    if headers:
        kwargs["default_headers"] = dict(headers)
    # OpenAI 推理族（gpt-5*/o*）拒 top_p：luna 回 HTTP 400 空 assistant → agno
    # "Unknown model error" / 流式空回（#1452）。temperature 仍可传。
    if top_p is not None and not supports_openai_reasoning_effort(llm_config.model):
        kwargs["top_p"] = top_p
    if force_json_output:
        # qwen / OpenAI 兼容协议：强制输出标准 JSON 字符串
        # 走 extra_body 透传给 dashscope；prompt 里必须含 "json" 字样
        if extra_body is None:
            extra_body = {}
        extra_body["response_format"] = {"type": "json_object"}
        kwargs["extra_body"] = extra_body
    if supports_openai_reasoning_effort(llm_config.model):
        effort = _openai_reasoning_effort(
            llm_config.model, reasoning_strength, llm_config.thinking_level, enable_thinking
        )
        if effort:
            kwargs["reasoning_effort"] = effort
