def _normalize_settle_meta_defaults(
    fiscal_raw: Dict[str, object],
    settle_meta_defaults: Dict[str, object],
    ctx: str,
) -> Dict[str, object]:
    fiscal = dict(fiscal_raw)
    settle_raw = fiscal.get("settle")
    if not isinstance(settle_raw, dict):
        return fiscal

    meta_raw = settle_raw.get("_meta", {})
    if meta_raw is None:
        meta_raw = {}
    if not isinstance(meta_raw, dict):
        raise SystemExit(f"{ctx}.fiscal.settle._meta 必须是 JSON 对象。")

    if "_meta_defaults" not in settle_raw:
        if settle_raw.get("_meta") is None and "_meta" in settle_raw:
            settle = dict(settle_raw)
            settle["_meta"] = {}
            fiscal["settle"] = settle
        return fiscal

    default_name = settle_raw.get("_meta_defaults")
    if not isinstance(default_name, str) or not default_name.strip():
        raise SystemExit(f"{ctx}.fiscal.settle._meta_defaults 必须是非空字符串。")
    default_key = default_name.strip()
    if default_key not in settle_meta_defaults:
        raise SystemExit(f"{ctx}.fiscal.settle._meta_defaults 指向未知默认组：{default_name}。")
    defaults_raw = settle_meta_defaults[default_key]
    if not isinstance(defaults_raw, dict):
        raise SystemExit(f"content/regions.json.settle_meta_defaults.{default_key} 必须是 JSON 对象。")

    settle = dict(settle_raw)
    settle["_meta"] = _deep_merge_content_defaults(defaults_raw, meta_raw)
    settle.pop("_meta_defaults", None)
    fiscal["settle"] = settle
    return fiscal

def _commission_appointment_fields(
    appointment: object, *, source: Provenance,
) -> Tuple[Optional[Dict[str, Any]], Optional[RejectedItem]]:
    """交办上的任免载荷；缺 name/office（任命）→ invalid_shape。"""
    if not appointment:
        return None, None
    if not isinstance(appointment, Mapping):
        return None, RejectedItem(
            item={"raw_value": appointment}, reason="任免载荷须为对象",
            category="invalid_shape", source=source,
        )
    action = str(
        appointment.get("appoint_action") or appointment.get("action") or "任命"
    ).strip() or "任命"
    if action not in {"任命", "罢免"}:
        return None, RejectedItem(
            item=dict(appointment), reason=f"任免动作非法：{action}",
            category="invalid_enum", source=source,
        )
    name = str(appointment.get("name") or "").strip()
    office = str(appointment.get("office") or appointment.get("new_office") or "").strip()
    if not name:
        return None, RejectedItem(
            item=dict(appointment), reason="任免声明缺 name",
            category="invalid_shape", source=source,
        )
    if action == "任命" and not office:
        return None, RejectedItem(
            item=dict(appointment), reason="任命声明缺 office",
            category="invalid_shape", source=source,
        )
    payload: Dict[str, Any] = {"name": name, "office": office, "appoint_action": action}
    mode = appointment.get("mode")
    if mode is not None:
        if not isinstance(mode, str) or mode not in {"ordinary", "midzhi"}:
            return None, RejectedItem(
                item=dict(appointment), reason=f"任免模式非法：{mode}",
                category="invalid_enum", source=source,
            )
        payload["mode"] = mode
    tenure = str(
        appointment.get("appointment_tenure") or appointment.get("任别") or ""
    ).strip()
    if tenure:
        payload["appointment_tenure"] = tenure
    # Typed 任所原样透传；不从官名推断（地方/督抚/边镇任命必填；中央可空）。
    seat = str(
        appointment.get("region_id") or appointment.get("任所") or ""
    ).strip()
    if seat:
        payload["region_id"] = seat
    return payload, None

def _apply_recovery_driven_transfers(
    db: GameDB,
    state: GameState,
    *,
    commit: bool = True,
) -> Tuple[List[Dict[str, object]], List[Dict[str, object]]]:
    """#652/0087：赈济/招抚屯田回流单核（确定性；LLM 零产回流）。

    触发：带 recovery 身份的 grant_allocation（赈灾/招抚屯田）+ 属地 region +
    本回合已付代价 + 已落结构化执行判决。基线=实抵万两×RECOVERY_PERSONS_PER_WAN，
    再经执行 outcome 成色折减；经 _apply_population_transfers reason=回流 唯一落库。
    幂等键 (dossier_id, turn)：同键不双扣池。立即开仓/#522 pacification 不在此列。
    """
    if db.population_unit != POPULATION_UNIT_PERSONS:
        return [], []
    turn = int(state.turn)
    # 月份推进事务只执行一次；同一案在本次扫描内仅回流一次。
    seen_keys: set[tuple[int, int]] = set()

    records: List[Dict[str, object]] = []
    remaining_by_region: Dict[str, int] = {}
    rows = db.conn.execute(
        """
        SELECT id, status, target_kind, target_id, payload_json,
               execution_outcome, closed_turn
        FROM decree_dossiers
        WHERE action_type='grant_allocation'
        ORDER BY id
        """
    ).fetchall()
    for row in rows:
        dossier_id = int(row["id"])
        if (dossier_id, turn) in seen_keys:
            continue
        try:
            payload = json.loads(str(row["payload_json"] or "{}"))
        except (TypeError, ValueError):
            continue
        if not isinstance(payload, dict):
            continue
        grant_action = str(payload.get("grant_action") or "").strip()
        if grant_action not in RECOVERY_GRANT_ACTIONS:
            continue
        target_kind = str(row["target_kind"] or payload.get("target_kind") or "").strip()
        region_id = str(row["target_id"] or payload.get("target_id") or "").strip()
        if target_kind != "region" or not region_id:
            continue
        if db.conn.execute("SELECT 1 FROM regions WHERE id=?", (region_id,)).fetchone() is None:
            continue
        outcome = str(row["execution_outcome"] or "").strip()
        if outcome not in RECOVERY_OUTCOME_FACTORS:
            continue
        cadence = str(payload.get("cadence") or "").strip()
        closed_turn = int(row["closed_turn"] or 0)
        if cadence != "每月" and closed_turn != turn:
            continue
        factor = float(RECOVERY_OUTCOME_FACTORS[outcome])
        if factor <= 0:
            seen_keys.add((dossier_id, turn))
            continue
        if cadence == "每月":
            reconciled = [
                int(item["arrived_amount"])
                for item in db.list_dossier_reconciliations(dossier_id)
                if int(item.get("turn") or 0) == turn
            ]
            if reconciled:
                silver = max(0, sum(reconciled))
            else:
                paid_row = db.conn.execute(
                    "SELECT COALESCE(SUM(-delta), 0) FROM economy_ledger "
                    "WHERE origin_ref=? AND turn=? AND delta<0",
                    (f"dossier:{dossier_id}", turn),
                ).fetchone()
                silver = max(0, int(paid_row[0] or 0))
        else:
            silver = _recovery_effective_silver_wan(db, dossier_id, turn)
        if silver <= 0:
            continue
        raw_persons = silver * RECOVERY_PERSONS_PER_WAN * factor

def commitment_progress_payload(
    db: GameDB,
    state: GameState,
    row: sqlite3.Row,
    *,
    paid_this_month: int = 0,
    include_current_month: bool = False,
) -> Optional[Dict[str, object]]:
    keys = row.keys() if hasattr(row, "keys") else []
    if not str(row["commitment_kind"] if "commitment_kind" in keys else "").strip():
        return None
    gate = _commitment_stop_gate(row)
    remaining = _commitment_remaining_from_gate(gate, state, db) if gate else None
    paid_total = _latest_commitment_paid_total(db, int(row["id"])) + max(0, int(paid_this_month))
    # Fall back to state.turn (→ 0 elapsed) when origin_turn is unset — whether the
    # key is absent OR present-but-NULL/0. `int(row["origin_turn"] or 0)` would collapse
    # a NULL/0 to 0 and leak the absolute turn number into months_elapsed (#380 cmr:
    # gemini + coderabbit). Only a positive origin_turn is a real anchor.
    origin_turn_raw = row["origin_turn"] if "origin_turn" in keys else None
    try:
        origin_turn = int(origin_turn_raw)
    except (TypeError, ValueError):
        origin_turn = 0
    if origin_turn <= 0:
        origin_turn = int(state.turn)
    months_elapsed = max(0, int(state.turn) - origin_turn)
    if include_current_month:
        months_elapsed = int(months_elapsed) + 1
    payload: Dict[str, object] = {
        "months_elapsed": int(months_elapsed),
        "paid_total": int(paid_total),
    }
    if remaining is not None:
        if _commitment_gate_references_arrears(row):
            payload["remaining_arrears"] = float(remaining)
        else:
            payload["remaining_to_goal"] = int(remaining)
    return payload

