    if isinstance(parsed, Mapping):
        return str(parsed.get("severity") or "").strip()
    return ""

def qualitative_midzhi_markers(row: dict) -> list[str]:
    markers: list[str] = []
    mode = str(row.get("mode") or "").strip()
    if mode == "midzhi":
        markers.append("中旨")
    stigma = row.get("stigma") or []
    if isinstance(stigma, list):
        for item in stigma:
            if not isinstance(item, dict) or item.get("kind") != "midzhi":
                continue
            source = str(item.get("source_action") or "").strip()
            if source == "force_promulgated":
                label = "批红强颁"
            elif source == "rejected":
                label = "中旨打回"
            else:
                label = "中旨"
            if label not in markers:
                markers.append(label)
    if bool(row.get("was_force_promulgated")) and "批红强颁" not in markers:
        markers.append("批红强颁")
    return markers

def gather_impeachment_surge_candidates(state: GameState, db: GameDB) -> List[Dict[str, object]]:
    """Project canonical dynamic candidates from transformed dossier facts.

    Other disaster legs deliberately have no adapter until their owning producers
    provide a durable occurrence and responsibility interface.
    """
    facts = db.build_faction_denunciation_facts()
    situations = {
        str(item.get("faction") or ""): item
        for item in facts.get("faction_situations", [])
        if isinstance(item, dict)
    }
    personas_by_faction: Dict[str, List[Dict[str, object]]] = {}
    for item in facts.get("character_personas", []):
        if isinstance(item, dict):
            personas_by_faction.setdefault(str(item.get("faction") or ""), []).append(item)

    rows = db.conn.execute(
        "SELECT id,closed_turn,participant_roster,decree_text,execution_note,execution_outcome "
        "FROM decree_dossiers "
        "WHERE execution_outcome='transformed' AND closed_turn BETWEEN ? AND ? ORDER BY id",
        (max(0, int(state.turn) - 1), int(state.turn)),
    ).fetchall()
    candidates: List[Dict[str, object]] = []
    for row in rows:
        did = int(row["id"])
        # #622/#1260 单源：仅有旨外 durable 的变形才构成 deformation_exposure。
        if not db.dossier_has_beyond_intent(did):
            continue
        try:
            roster = json.loads(str(row["participant_roster"] or "[]"))
        except (TypeError, ValueError):
            continue
        if not isinstance(roster, list) or not roster:
            continue
        participant_ids = [
            str(item.get("character_id") or "").strip()
            for item in roster if isinstance(item, dict) and str(item.get("character_id") or "").strip()
        ]
        if len(participant_ids) != len(roster) or not participant_ids:
            continue
        liability = project_execution_liability_parties(roster)
        responsible_ids = [
            str(item.get("character_id") or "").strip() for item in liability
            if str(item.get("character_id") or "").strip()
        ]
        if not responsible_ids:
            continue
        # 存在门只看责任集；知情/协办离场不得 any() 否决整卷。
        placeholders = ",".join("?" for _ in responsible_ids)
        chars = db.conn.execute(
            f"SELECT name,faction,status FROM characters WHERE name IN ({placeholders})",
            responsible_ids,
        ).fetchall()
        char_by_name = {str(item["name"]): item for item in chars}
        if any(
            name not in char_by_name
            or str(char_by_name[name]["status"] or "") != "active"
            or not str(char_by_name[name]["faction"] or "").strip()
            for name in responsible_ids
        ):
            continue
        responsible_factions = list(dict.fromkeys(
            str(char_by_name[name]["faction"]) for name in responsible_ids
        ))
        # 闭集：在朝 participant ∪ 在朝 responsible（含仅 delegator_id 连坐）。
        union_ids = list(dict.fromkeys([*participant_ids, *responsible_ids]))
        missing = [name for name in union_ids if name not in char_by_name]
        if missing:
            missing_ph = ",".join("?" for _ in missing)
            for item in db.conn.execute(
                f"SELECT name,faction,status FROM characters WHERE name IN ({missing_ph})",
                missing,
            ).fetchall():
                char_by_name[str(item["name"])] = item
        eligible_target_ids = [
            name for name in union_ids
            if name in char_by_name
            and str(char_by_name[name]["status"] or "") == "active"
            and str(char_by_name[name]["faction"] or "").strip()

def format_army_changes(changes: List[Dict[str, object]]) -> str:
    # 拒收项(ADR 0008 决定 1)与 applied 项同列，但不是盘面变化，先滤掉。
    changes = [c for c in (changes or []) if not (isinstance(c, dict) and c.get("rejected"))]
    if not changes:
        return f"本{TURN_UNIT}未见明确军队盘面变化。"
    parts = []
    for change in changes:
        delta = change["delta"]
        field = str(change["field"])
        if delta is None:
            parts.append(f"{change['army']}{change['label']}改为{change['new']}（{change['reason']}）")
        elif field == "manpower":
            sign = "+" if int(delta) > 0 else ""
            parts.append(f"{change['army']}{change['label']}{sign}{int(delta)}人（{change['reason']}）")
        else:
            sign = "+" if int(delta) > 0 else ""
            parts.append(f"{change['army']}{change['label']}{sign}{int(delta)}（{change['reason']}）")
    return "；".join(parts) + "。"

def require_explicit_xiexang_fields(
    *,
    amount: object = 0,
    account: str = "",
    purpose: str = "",
    target_kind: str = "",
    target_id: str = "",
    cadence: str = "",
) -> Dict[str, Any]:
    """#1503 单一权威接缝：严格验形并归一 typed 字段。"""
    from ming_sim.strict_types import strict_int

    facts: list = []

    def _note(field: str, *, current: object, expected: object) -> None:
        facts.append({"field": field, "current": current, "expected": expected})

    try:
        n = strict_int(amount, accept_numeric_strings=False)
    except ValueError:
        n = 0
    if n <= 0:
        _note("amount", current=amount, expected={"type": "positive_int"})
    # #1620：太仓→国库唯一权威 resolve_grant_account；此处不再平行 if。
    canonical_account = resolve_grant_account(grant_action="协饷", account=account)
    if canonical_account not in {"国库", "内库"}:
        _note("account", current=account, expected=["国库", "内库"])
    purpose_cur = str(purpose or "").strip()
    if purpose_cur != "补饷":
        _note("purpose", current=purpose_cur or purpose, expected="补饷")
    canonical_target_kind = str(target_kind or "").strip()
    if canonical_target_kind not in XIEXIANG_TARGET_KINDS:
        _note(
            "target_kind",
            current=canonical_target_kind or target_kind,
            expected=sorted(XIEXIANG_TARGET_KINDS),
        )
    target_id_cur = str(target_id or "").strip()
    if not target_id_cur:
        _note("target_id", current=target_id, expected={"nonempty_str": True})
    cadence_value = str(cadence or "").strip()
    if cadence_value and cadence_value not in {"一次性", "每月"}:
        _note(
            "cadence",
            current=cadence_value,
            expected=["一次性", "每月", ""],
        )
    if facts:
        raise IncompleteXiexangPayloadError(field_failures=facts)
    return {
        "amount": n,
        "account": canonical_account,
        "purpose": "补饷",
        "target_kind": canonical_target_kind,
        "target_id": target_id_cur,
    }

def appointment_tenure_from(payload: dict[str, object]) -> str:
    """读取公开中文字段或内部英文别名；仅无任别字段的旧载荷按真除兜底。"""
    keys = [key for key in ("任别", "appointment_tenure") if key in payload]
    if not keys:
        return DEFAULT_APPOINTMENT_TENURE

    for key in keys:
        value = payload[key]
        if not isinstance(value, str) or value not in APPOINTMENT_TENURES:
            raise ValueError(f"任别非白名单：{value}")
    return payload[keys[0]]  # type: ignore[return-value]

