        source="grant_allocation", origin_ref=origin_ref, commit=False,
    )

def adjust_classes(
    self,
    deltas: Dict[str, Dict[str, int]],
    commit: bool = True,
) -> List[Dict[str, object]]:
    """deltas 结构：{ key: {satisfaction: +/-N, leverage: +/-N} }
    key 形式：'农民' (全国) 或 '农民@shaanxi' (省级)。

    查无此阶级（名/省不匹配）→ missing_ref 逐项拒收留痕（ADR 0008 决定 1，#14/#63
    死法 3）；入参经 _apply_class_dict 预清洗。返回拒收项列表，桥接自动收。
    """
    rejected: List[Dict[str, object]] = []
    for key, fields in deltas.items():
        if not fields:
            continue
        if "@" in key:
            name, region_id = key.split("@", 1)
        else:
            name, region_id = key, ""
        row = self.conn.execute(
            "SELECT satisfaction, leverage FROM classes WHERE name = ? AND region_id = ?",
            (name.strip(), region_id.strip()),
        ).fetchone()
        if not row:
            rejected.append({
                "name": key, "rejected": True, "category": "missing_ref",
                "reason": f"class_delta 查无此阶级「{key}」（未入 classes 表）",
                "item": {key: fields},
            })
            continue
        sat = int(row["satisfaction"]) + int(fields.get("satisfaction", 0) or 0)
        lev = int(row["leverage"]) + int(fields.get("leverage", 0) or 0)
        sat = max(0, min(100, sat))
        lev = max(0, min(100, lev))
        self.conn.execute(
            "UPDATE classes SET satisfaction = ?, leverage = ?, updated_at = CURRENT_TIMESTAMP "
            "WHERE name = ? AND region_id = ?",
            (sat, lev, name.strip(), region_id.strip()),
        )
    if commit:
        self.conn.commit()
    return rejected

def knowledge_exclusions_for_source(self, source_id: str) -> List[str]:
    """Return the durable secrecy boundary attached to a source record."""
    source = str(source_id or "")
    row = self.conn.execute(
        "SELECT excluded_names FROM character_knowledge_events WHERE source_id=? "
        "ORDER BY id LIMIT 1", (source,)
    ).fetchone()
    if row is not None:
        try:
            return [str(name) for name in json.loads(row["excluded_names"] or "[]")]
        except (TypeError, ValueError):
            return []
    # #883 CR R1 S2: bare ``secret_order:`` shared *sources* are no longer
    # produced (create/update → private briefs; production disclosure →
    # ``secret_order_disclosure:``; register gate rejects the prefix).
    # Retained: ``record_public_knowledge_event`` still inherits exclusions
    # by looking up secret_orders when source_id is ``secret_order:N`` —
    # exercised by AC harness paths (test_character_knowledge_489 /
    # test_minister_context / test_web_chat_serialization_393). Without
    # this branch those writes lose the blacklist. session.py only DELETEs
    # legacy sources with this prefix; no live production producer.
    match = re.fullmatch(r"secret_order(?:_brief)?:(\d+)", source)
    if match:
        order_id = int(match.group(1))
        order = self.conn.execute(
            "SELECT excluded_names FROM secret_orders WHERE id=?", (order_id,)
        ).fetchone()
        if order is not None:
            try:
                return [str(name) for name in json.loads(order["excluded_names"] or "[]")]
            except (TypeError, ValueError):
                return []
    # #1829 reopen：公开说法排除名单与正文同表，按 public_saying:<id> 回查。
    match = re.fullmatch(r"public_saying:(\d+)", source)
    if match:
        saying = self.conn.execute(
            "SELECT excluded_names FROM public_sayings WHERE id=?",
            (int(match.group(1)),),
        ).fetchone()
        if saying is not None:
            try:
                return [str(name) for name in json.loads(saying["excluded_names"] or "[]")]
            except (TypeError, ValueError):
                return []
        return []
    row = self.conn.execute(
        "SELECT excluded_names FROM character_knowledge_sources WHERE source_id=?", (source,)
    ).fetchone()
    if row is not None:
        try:
            return [str(name) for name in json.loads(row["excluded_names"] or "[]")]
        except (TypeError, ValueError):
            return []
    return []

def _scan(section: str, items: list) -> None:
    for item in items:
        if not isinstance(item, dict):
            continue
        if item.get("rejected"):
            report_section = str(item.get("report_section") or section)
            collector.record(report_section, RejectedItem(
                # item_json = 原始 delta 项（ADR 决定 5「原 item 原样保留」）：迁约
                # producer 在 wrapper 里带原件（'item' 键）则解包,否则兜底存 wrapper
                # （ship-pre r3——存整个 wrapper 会让重放分析消费到嵌套形状）。
                # 按 'item' 键**存在性**解包（非值类型）：原 isinstance(dict/list/str) 判会把
                # 标量/null 原件（如 close_issues:[null]/[42] 的非 dict 拒收）误存成 wrapper、
                # 丢原件保真——key 在即解包，覆盖标量原件（cmr close-issues r5 codex）。
                item=item["item"] if "item" in item else item,
                # ADR「拒收行必带人读原因」在此集中守门：producer 漏给则合成非空兜底
                # ——规则写一处，新 section 免疫同类缺陷（fix-coverage 处方，cmr S0 r3）。
                reason=str(item.get("reason") or "") or f"拒收（{report_section} 未注明原因）",
                category=str(item.get("report_category") or item.get("category") or "legacy_inline"),
                source=source,
            ), turn)
        for subkey, subvalue in item.items():
            if isinstance(subvalue, list):
                nested_section = f"{section}.{subkey}"
                if nested_section == "issue_summary.closes.applied_person_changes":
                    continue
                _scan(nested_section, subvalue)

def normalize_locality_scope(raw: object) -> str:
    """{'全国'/'单省'/'无'/缺省 → national/single/none}；枚举外 fail-loud。"""
    if raw is None:
        return "none"
    text = str(raw).strip()
    if not text:
        return "none"
    if text in _SCOPE_ALIASES:
        scope = _SCOPE_ALIASES[text]
    else:
        scope = text
    if scope not in LOCALITY_SCOPES:
        raise ValueError(f"locality_scope 非法：{raw!r}")
    return scope

def _commitment_ongoing_effects_for_settlement(row: sqlite3.Row, ongoing: Dict[str, object]) -> Dict[str, object]:
    if not _commitment_gate_references_arrears(row):
        return ongoing
    gate_army_ids = _commitment_arrears_gate_army_ids(row)
    normalized = dict(ongoing)
    for key in ("economy", "economy_moves"):
        economy = ongoing.get(key)
        if not isinstance(economy, list):
            continue
        normalized_economy: List[object] = []
        for move in economy:
            if not isinstance(move, dict):
                normalized_economy.append(move)
                continue
            item = dict(move)
            try:
                delta = _strict_int(item.get("delta"))
            except (TypeError, ValueError):
                delta = 0
            if delta < 0:
                item["purpose"] = "补饷"
                if (
                    len(gate_army_ids) == 1
                    and not str(item.get("target_id") or "").strip()
                    and not str(item.get("目标编号") or "").strip()
                    and not str(item.get("target_kind") or item.get("目标类型") or "").strip()
                ):
                    item["target_kind"] = "army"
                    item["target_id"] = gate_army_ids[0]
            normalized_economy.append(item)
        normalized[key] = normalized_economy
    return normalized

