def recognize_audience_command(message: str) -> str:
    """收夜/留侍口令结构化判词（#526）。

    确定性封闭集（COURT_BREAK / AMBIGUOUS_CLOSE / STAY_ATTEND）；引擎不重解析散文。
    不进 ACTION_CLUSTERS；非第二 parser（无自由散文正则启发）。
    无耗时软判——同步直调即可；坏 shape 由 normalize 归一，不在此宽吞异常。
    """
    from ming_sim.constants import (
        AMBIGUOUS_CLOSE_COMMANDS,
        COURT_BREAK_COMMANDS,
        STAY_ATTEND_COMMANDS,
    )

    text = str(message or "").strip()
    if not text:
        return CMD_NONE
    lowered = text.lower()
    if text in STAY_ATTEND_COMMANDS or lowered in STAY_ATTEND_COMMANDS:
        return CMD_STAY_ATTEND
    if lowered in COURT_BREAK_COMMANDS or text in COURT_BREAK_COMMANDS:
        return CMD_CLOSE_NIGHT
    if text in AMBIGUOUS_CLOSE_COMMANDS or lowered in AMBIGUOUS_CLOSE_COMMANDS:
        return CMD_AMBIGUOUS_CLOSE
    return CMD_NONE

def _all_roster_identity_forms(*, content: Any) -> Dict[str, List[str]]:
    """canon → 规范名+别名列表；供截断前缀唯一性判定。"""
    out: Dict[str, List[str]] = {}
    chars = getattr(content, "characters", None) or {} if content is not None else {}
    for key, ch in chars.items():
        canon = str(key or "").strip()
        if not canon:
            continue
        forms = [canon]
        for raw in getattr(ch, "aliases", None) or []:
            alias = str(raw or "").strip()
            if alias and alias not in forms:
                forms.append(alias)
        out[canon] = forms
    return out

def _cli_stream_safe_prefix(text: str) -> tuple[str, str]:
    """Release text that cannot belong to a trailing recommendation envelope."""
    marker_at = text.rfind(_CLI_RECOMMENDATION_PREFIX)
    if marker_at >= 0:
        return text[:marker_at], text[marker_at:]
    keep = 0
    for length in range(1, min(len(text), len(_CLI_RECOMMENDATION_PREFIX) - 1) + 1):
        if text.endswith(_CLI_RECOMMENDATION_PREFIX[:length]):
            keep = length
    return (text[:-keep], text[-keep:]) if keep else (text, "")

def _roster_identity_forms(canon: str, *, content: Any) -> List[str]:
    """名册事实：规范名 + aliases（与 #1428 事实块同源，机械列表）。"""
    forms: List[str] = []
    name = str(canon or "").strip()
    if name:
        forms.append(name)
    ch = None
    if content is not None:
        chars = getattr(content, "characters", None) or {}
        ch = chars.get(name)
    for raw in getattr(ch, "aliases", None) or []:
        alias = str(raw or "").strip()
        if alias and alias not in forms:
            forms.append(alias)
    return forms

def canonicalize_delivery_unit(unit: object, target: object) -> tuple[str, float]:
    raw = str(unit or "").strip()
    try:
        qty = float(target)
    except (TypeError, ValueError):
        raise CovertContractError("密令确认缺少可数交付目标") from None
    if qty <= 0.0:
        raise CovertContractError("密令确认交付目标必须为正数")
    if raw not in CANONICAL_UNITS:
        raise CovertContractError("密令确认交付单位须为万两/人犯/万亩")
    return raw, float(qty)

def _is_punitive_change(item: Dict[str, object]) -> bool:
    action = str(item.get("动作") or item.get("action") or "").strip()
    if action == "罢黜":
        return True
    if action != "处置":
        return False
    status = str(item.get("status") or "").strip()
    return status in _PUNISH_STATUSES

def _apply_military_order_station_effect(
    self, state, *, army_id: str, station: str, actor: str, reason: str,
    origin_ref: str, station_region: str = "",
) -> None:
    """军令调驻面：既有军 station(+可选 station_region) → army 写核；不得 new_armies。

    #659：只改人读驻地/结构化驻地；不触 pay_source_region。仅 station 无 region
    时只改人读字段，region 保持原值（禁止从 station 文本反推）。
    """
    dest = str(station or "").strip()
    dest_region = str(station_region or "").strip()
    if not dest and not dest_region:
        return
    if not army_id:
        raise ValueError("军令调驻缺少军队 target")
    existing = self.conn.execute(
        "SELECT id FROM armies WHERE id = ?", (army_id,),
    ).fetchone()
    if existing is None:
        raise ValueError(
            f"军令调驻引用未入库军队 '{army_id}'（既有军调驻不得 new_armies）"
        )
    from ming_sim.models import Event
    pseudo = Event(
        id="military_order", title="军令调遣", kind="圣旨", summary="",
        urgency=0, severity=0, credibility=100, interests=[], audiences=[],
    )
    delta: Dict[str, object] = {"reason": reason}
    if dest:
        delta["station"] = dest
    if dest_region:
        delta["station_region"] = dest_region
    changes = self.apply_army_deltas(
        state, pseudo, None, actor or "军令",
        {army_id: delta},
        commit=False,
        origin_ref=origin_ref,
        require_origin=True,
    )
    # #521 r1：目标 station=当前站时 army 写核空接受=幂等 noop 成功，
    # 不得当硬失败以致同批职守变更回滚。
    rejected = [
        c for c in changes
        if isinstance(c, dict) and c.get("rejected")
    ]
    if rejected:
        fail_reason = str(rejected[0].get("reason") or "")
        raise ValueError(fail_reason or "军令调驻物化失败")

def _commit_office_action(
    self, state: GameState, pa: Dict[str, object], payload: Dict[str, object],
    content,
) -> set[str]:
    """任免(office)落库并返回 canonical applied 中受影响的正式人物。
    - 任命既有官 → 升迁/调任:set_character_office(改官、仍 active),不当新人(apply_appointment
      对在册者命中即拒、会标 failed);
    - 任命朝臣(新任/升迁/调任)→ person-only canonical adapter → apply_office_appointment
      唯一落地核(dead-reject / 非active→激活 / 顶替去重);
    - 罢免:_find_existing_minister 解 alias + ming-guard(外藩/后宫/不在册不接),dismissed+同步清内存 office。
    缺 content(无法查重/注册)→ 空集合标 failed,不静默。跨模块函数运行期 lazy import 避免 db↔session/issues 循环。"""
    if content is None:
        return set()
    from ming_sim.session import _find_existing_minister
    name = str(payload.get("name") or "").strip()
    if not name:
        return set()
    office = str(payload.get("office") or "")
    if pa["action"] == "任命":
        # 朝臣任命/升迁/调任 → person-only adapter（不经 full settlement recovery）。
        reason = str(payload.get("reason") or "奉旨任免")
        office_type = str(payload.get("office_type") or "").strip()
        try:
            appointment_tenure = appointment_tenure_from(payload)
        except ValueError:
            return set()
        recommendation = payload.get("recommendation")
        staged_candidate = recommendation.get("candidate") if isinstance(recommendation, dict) else None
        recommender = str(recommendation.get("recommender") or pa["minister_name"]) if isinstance(recommendation, dict) else ""
        # #1583：批内已在 apply_dossier_verdicts / 批红序前统一校验过荐人快照时，
        # 跳过二次校验，避免前序任免改盘面把后序同快照误判过期。
        if not getattr(self.conn, "_recommendation_snapshots_prevalidated", False):
            if recommendation is not None and (
                not isinstance(staged_candidate, dict)
                or not recommender
            ):
                return set()
            if isinstance(staged_candidate, dict):
                from ming_sim.recommendations import validate_recommendation_snapshot
                if staged_candidate.get("name") != name or not validate_recommendation_snapshot(
                    self, state, recommender, staged_candidate
                ):
                    return set()
        elif recommendation is not None and (
            not isinstance(staged_candidate, dict)
            or not recommender
            or staged_candidate.get("name") != name
        ):
            return set()
        # A recommendation event is provenance for this exact staged
        # candidate.  Keep the appointment and event in one transaction so
        # a failure while recording cannot leave the appointment adopted
        # without its auditable recommendation.
        recommendation_reason = ""
        if isinstance(recommendation, dict):
            recommendation_reason = str(payload.get("reason") or "")
            if not recommendation_reason.strip():
                raise ValueError("荐人双边缺非空荐词语境：payload.reason 必填")
            reason = recommendation_reason
        from ming_sim.issues import apply_person_changes_only
        person_item = {
            "name": name, "动作": "任命", "office": office,
            "office_type": office_type, "任别": appointment_tenure,
            "reason": reason, "origin_ref": "盘面自发",
        }
        seat = str(
            payload.get("region_id")
            or payload.get("任所")
            or payload.get("辖区")
            or ""
        ).strip()
        if seat:
            person_item["region_id"] = seat
        applied = apply_person_changes_only(
            self, state,
            [person_item],
            content=content, llm_config=self.llm_config,
        )
        affected = self._affected_people_from_applied_rows(
            applied.get("applied_person_changes", []),

def _grant_escort_presence(
    self, dossier_id: int,
) -> Tuple[bool, Optional[int], str]:
    """被护案卷侧查入链：护卫/稽核在场与否（0054 逐路独立）。"""
    for link in self.list_dossier_links(int(dossier_id), direction="incoming"):
        relation = str(link.get("relation_type") or "").strip()
        if relation in _GRANT_ESCORT_RELATIONS:
            return True, int(link["source_dossier_id"]), relation
    return False, None, ""

def _merge_directive_payload(
    self, existing_json: object, new_payload: Dict[str, object],
) -> Dict[str, object]:
    """改草保留未修改的机械字段；显式新值覆盖后统一校验。

    #658：普通 triad 与御笔 target 互斥生命周期——
    普通改草不得继承旧 target；纯强推改草不得继承旧 triad。
    """
    old = self._decode_directive_dossier_payload(existing_json)
    incoming = dict(new_payload or {})
    old_roster = self._normalize_participant_roster(old.get("participant_roster") or [])
    new_roster = self._normalize_participant_roster(incoming.get("participant_roster") or [])
    if not new_roster:
        incoming.pop("participant_roster", None)
    else:
        incoming["participant_roster"] = old_roster + [
            item for item in new_roster if item not in old_roster
        ]
    # 先对 incoming 互斥分类（并存即拒），再决定从 old 继承哪些字段
    incoming_kind = (
        classify_directive_structured_kind(incoming)
        if incoming else "empty"
    )
    merged = {**old, **incoming}
    if incoming_kind == "ordinary":
        merged.pop("target_dossier_id", None)
        merged.pop("目标案卷ID", None)
    elif incoming_kind == "push":
        # 只清互斥 ordinary triad，保留 text/actor 等非互斥字段
        for key in ("dossier_action_type", "target_kind", "target_id"):
            merged.pop(key, None)
        push_id = imperial_push_target_dossier_id(incoming)
        if push_id is None:
            push_id = imperial_push_target_dossier_id(merged)
        if push_id is not None:
            merged["target_dossier_id"] = push_id
            merged.pop("目标案卷ID", None)
    # 合并结果再过互斥权威（old 残留 + incoming 部分字段仍可能冲突）
    classify_directive_structured_kind(merged)
    requested = str(merged.get("dossier_action_type") or "")
    if incoming_kind == "push":
        # 复用既有 push 归一化（保留 text/actor/mode）
        return self._normalize_directive_dossier_payload(
            merged, content=self.content,
            current_turn=int(self.conn.execute(
                "SELECT turn FROM game_state WHERE id=1"
            ).fetchone()["turn"]),
        )
    normalized = self._normalize_directive_dossier_payload(
        merged, content=self.content,
        current_turn=int(self.conn.execute(
            "SELECT turn FROM game_state WHERE id=1"
        ).fetchone()["turn"]),
    )
    if requested and normalized.get("dossier_action_type") != requested:
        raise ValueError("旨稿机械载荷不完整或非法，拒绝改草")
    return normalized

def apply_character_power_changes(
    self,
    changes: List[Dict[str, object]],
    commit: bool = True,
) -> List[Dict[str, object]]:
    """据 extractor 输出改人物 power_id（降将/叛臣/归正）。new_power 须为合法 power id。"""
    applied: List[Dict[str, object]] = []
    if not isinstance(changes, list):
        return applied
    valid_powers = {r["id"] for r in self.conn.execute("SELECT id FROM powers").fetchall()}
    for raw in changes:
        if not isinstance(raw, dict):
            continue
        name = str(raw.get("name") or raw.get("姓名") or "").strip()
        new_power = str(raw.get("new_power") or raw.get("新势力") or "").strip()
        reason = str(raw.get("reason") or raw.get("原因") or "")
        if not name or not new_power:
            applied.append({
                "rejected": True, "category": "invalid_enum",
                "reason": "character_power_changes 缺 name/new_power",
                "item": raw,
            })
            continue
        if new_power not in valid_powers:
            applied.append({
                "name": name, "new_power": new_power, "rejected": True,
                "category": "hallucinated_id",
                "reason": f"character_power_changes new_power '{new_power}' 未在 powers",
                "item": raw,
            })
            continue
        row = self.conn.execute(
            "SELECT power_id, faction FROM characters WHERE name=?", (name,)
        ).fetchone()
        if row is None:
            applied.append({
                "name": name, "new_power": new_power, "rejected": True,
                "category": "missing_ref",
                "reason": f"character_power_changes 人物 '{name}' 未入库",
                "item": raw,
            })
            continue
        old_power = row["power_id"] or "ming"
        if old_power == new_power:
            continue
        self.conn.execute(
            "UPDATE characters SET power_id = ? WHERE name = ?",
            (new_power, name),
        )
        # #177 R2: power_id 跨 ming 边界翻转后即时重算原派系 leverage
        # （与 set_character_status / set_character_office 钩子一致）。
        # sourcery R1：faction 为空跳过；只在真跨 ming 边界（old/new 有一方是 ming）时重算
        # —— _faction_office_weight_sum 按 power_id='ming' 过滤，非 ming↔非 ming 翻转不改权重和。
        faction = str(row["faction"] or "")
        if faction and (old_power == "ming" or new_power == "ming"):
            self.recompute_faction_leverage(faction)
        applied.append({"name": name, "old_power": old_power, "new_power": new_power, "reason": reason})
    if commit:
        self.conn.commit()
    return applied

def ensure_column(self, table: str, column: str, definition: str) -> bool:
    """确保 table.column 存在。返回 True=本次新增了该列（真·一次性迁移），
    False=列已存在（后续 load 的常态）。多数 caller 忽略返回值即可。"""
    columns = {row["name"] for row in self.conn.execute(f"PRAGMA table_info({table})").fetchall()}
    if column not in columns:
        self.conn.execute(f"ALTER TABLE {table} ADD COLUMN {column} {definition}")
        return True
    return False

def normalize_office(office: str) -> str:
    """官职多职统一为半角逗号分隔：旧「兼/兼掌/兼署」与全角「，」「、」一律归一逗号，
    去空分项、去重、保序。是 office 字段落库的唯一规范化入口——所有写 characters.office
    的路径都过它，保证去重/顶缺时能按逗号分项匹配。"""
    s = (office or "").strip()
    if not s:
        return ""
    s = s.replace("兼掌", ",").replace("兼署", ",").replace("兼", ",")
    s = s.replace("，", ",").replace("、", ",")
    seen: set = set()
    parts: List[str] = []
    for p in (x.strip() for x in s.split(",")):
        if p and p not in seen:
            seen.add(p)
            parts.append(p)
    return ",".join(parts)

def transition_decree_dossier(
    self, dossier_id: int, new_status: str, *, commit: bool = True,
) -> None:
    row = self.conn.execute(
        "SELECT status,action_type,payload_json,execution_outcome FROM decree_dossiers WHERE id=?",
        (int(dossier_id),),
    ).fetchone()
    if row is None:
        raise KeyError(f"案卷不存在：{dossier_id}")
    old_status = str(row["status"])
    if new_status == old_status:
        return
    if new_status not in self._DOSSIER_TRANSITIONS[old_status]:
        raise ValueError(f"案卷非法迁移：{old_status} -> {new_status}")
    if old_status == "promulgated" and new_status == "closed":
        payload = json.loads(str(row["payload_json"] or "{}"))
        if self._dossier_has_execution_surface(row["action_type"], payload):
            raise ValueError("带执行判定面的案卷不得从 promulgated 直接 closed")
        if not str(row["execution_outcome"] or ""):
            raise ValueError("直达结案仍须填写执行格")
    closed_sql = ", closed_at=CURRENT_TIMESTAMP" if new_status == "closed" else ""
    self.conn.execute(
        f"UPDATE decree_dossiers SET status=?,updated_at=CURRENT_TIMESTAMP{closed_sql} "
        "WHERE id=?",
        (new_status, int(dossier_id)),
    )
    self._commit_dossier_write(commit)

def mark_settled(self, decree_ref: str) -> int:
    ref = str(decree_ref or "").strip()
    owns = connection_owns_transaction(self._conn)
    cur = self._conn.execute(
        "UPDATE staged_declarations SET status='settled' "
        "WHERE decree_ref=? AND status='staged'",
        (ref,),
    )
    if owns:
        self._conn.commit()
    return int(cur.rowcount or 0)

def latest_error_pack_for_turn(db_path: object, turn: int) -> Optional[str]:
    """同 DB + turn 最新完整错误包绝对路径；无则 None（ADR 0008 决定 7 恢复面）。

    身份取 manifest.db_path + turn，
    禁跨存档串包（同 user-data 下另一 DB 的更高 attempt 不得入选）。
    目录扫描/条目 stat 的 OSError 视为无诊断包——不得拖垮 settling 恢复面。
    """
    root = error_packs_root()
    try:
        if not root.exists():
            return None
        entries = list(root.iterdir())
    except OSError:
        return None
    expected_db_path = str(db_path)
    prefix = f"turn{int(turn)}_attempt"
    best: Optional[Path] = None
    best_n = -1
    for path in entries:
        try:
            if not (path.is_dir() and path.name.startswith(prefix)):
                continue
            n = int(path.name[len(prefix):])
        except (OSError, ValueError):
            continue
        manifest = _read_complete_pack_manifest(path)
        if manifest is None:
            continue
        if (
            str(manifest.get("db_path")) != expected_db_path
            or manifest.get("turn") != int(turn)
        ):
            continue
        if n > best_n:
            best_n = n
            best = path
    if best is None:
        return None
    try:
        return str(best.resolve())
    except OSError:
        return None

def _apply_bandit_absorptions(
    db: GameDB,
    state: GameState,
    absorptions: object,
    *,
    commit: bool = True,
) -> Tuple[List[Dict[str, object]], List[Dict[str, object]], List[Dict[str, object]]]:
    """#652/0087：流民投贼吸收原子 applier。

    LLM 只产 typed 请求；本核：actual=min(requested, 省池)→扣流民池（无农民对端，
    0087 兵源出口单侧出池）→仅 actual>0 允许实力正增（δ=actual//换算率，0–100 clamp
    走 apply_power_deltas）。超池/非法 id/零池正请求 → 逐项拒收留痕。
    返回 (applied_absorptions, rejections, power_changes)。
    """
    should_commit = bool(commit) and db.owns_transaction()
    applied: List[Dict[str, object]] = []
    rejected: List[Dict[str, object]] = []
    power_changes: List[Dict[str, object]] = []
    items = absorptions if isinstance(absorptions, list) else []
    # 仅 substrate 人口径新档开环；legacy 不误开（对齐 #649/#650）。
    if db.population_unit != POPULATION_UNIT_PERSONS:
        for item in items:
            rejected.append({
                "rejected": True, "category": "invalid_enum",
                "reason": "bandit_absorptions 仅适用于 population_unit='人' 的人口池档",
                "item": item if isinstance(item, dict) else {"raw_value": item},
            })
        return applied, rejected, power_changes

    for item in items:
        if not isinstance(item, dict):
            rejected.append({
                "rejected": True, "category": "invalid_shape",
                "reason": "bandit_absorptions 项必须是 object(dict)",
                "item": {"raw_value": item},
            })
            continue

        def _reject(category: str, reason: str) -> None:
            rejected.append({
                "rejected": True, "category": category,
                "reason": reason, "item": item,
            })

        extra = sorted(set(item) - BANDIT_ABSORPTION_FIELDS)
        if extra:
            _reject(
                "invalid_enum",
                f"bandit_absorptions 白名单外字段 {extra}"
                f"（合法字段：region_id/power_id/requested_count/origin_ref）",
            )
            continue

        region_id = str(item.get("region_id") or "").strip()
        power_id = str(item.get("power_id") or "").strip()
        origin_ref = str(item.get("origin_ref") or "").strip()
        if not region_id:
            _reject("missing_ref", "bandit_absorptions 缺 region_id")
            continue
        region_row = db.conn.execute(
            "SELECT controlled_by FROM regions WHERE id=?", (region_id,)
        ).fetchone()
        if region_row is None:
            _reject("missing_ref", f"bandit_absorptions 未知 region_id：{region_id!r}")
            continue
        if str(region_row["controlled_by"] or "") != "ming":
            _reject("missing_ref", f"bandit_absorptions 非明省不可吸收：{region_id!r}")
            continue
        if not power_id or not _is_bandit_power_id(power_id):
            _reject(
                "invalid_enum",
                f"bandit_absorptions power_id 须为流寇股（bandits/bandit_*）：{power_id!r}",
            )
            continue
        power_row = db.conn.execute(
            "SELECT id FROM powers WHERE id=?", (power_id,)
        ).fetchone()
        if power_row is None:
            _reject("hallucinated_id", f"bandit_absorptions 引用未入库势力 '{power_id}'")
            continue

def _commitment_arrears_remaining_text(amount: object) -> str:
    text = _approx_wanliang(amount)
    if text.startswith("欠饷"):
