def _initiative_resolve_pairing_warnings(
    title: str, tags: object, ongoing_effects: object, effect: object,
) -> List[str]:
    """国策结案实体后果强制配对守门（#45/#46）——仅在 initiative 结案处调用。
    返回缺配对的告警串列表（空=无缺漏）。warn-only，调用方 surface、不阻断。"""
    tag_list = tags if isinstance(tags, (list, tuple)) else []
    blob = str(title or "") + " " + " ".join(str(t) for t in tag_list)
    effect = effect if isinstance(effect, dict) else {}
    warns: List[str] = []

    # 练军/募营 须落 new_armies；调将 须落人物变更——分别判，不混为一谈（练军只挂调任仍缺军籍、
    # 调将只挂建军仍缺主将调任，混判会互相消音，CMR codex）。office_changes 是 ADR 0009 死键、
    # _apply_issue_entities 不读，不纳入 has_office（纳入会消音本该响的告警，CMR gemini）。
    needs_army = any(p in blob for p in _MILITARY_RAISE_PHRASES)
    needs_office = any(p in blob for p in _MILITARY_MOVE_PHRASES)
    if needs_army or needs_office:
        # 形对：_apply_issue_entities 只落 list 的 new_armies/人物变更/character_status_changes、
        # dict 的 army_delta；畸形容器（字符串/错类型）不算真配对，不该消音告警（PR#107 codex）。
        has_army = _nonempty_list(effect.get("new_armies")) or _nonempty_dict(effect.get("army_delta"))
        has_office = (
            _nonempty_list(effect.get("人物变更"))
            or _nonempty_list(effect.get("character_status_changes"))
        )
        if needs_army and not has_army:
            warns.append(
                f"军事国策「{str(title)[:16]}」结案无 new_armies 配对（练军/募营疑未建军籍，#46）"
            )
        if needs_office and not has_office:
            warns.append(
                f"军事国策「{str(title)[:16]}」结案无人物变更配对（调将疑未落主将调任，#46）"
            )

    if any(p in blob for p in _FISCAL_RECURRING_PHRASES):
        # 只查国策自身 effect/ongoing 的月度 economy；顶层 fiscal_creates 不在本纯函数视野内，
        # 故告警文案不声称查了它——若另经 fiscal_creates 立账可忽略本提示（CMR claude）。
        if not _has_economy_entry(effect) and not _has_economy_entry(ongoing_effects):
            warns.append(
                f"经制国策「{str(title)[:16]}」结案无月度 economy 配对"
                "（疑月经费/俸饷未立常设月支；若已另经 fiscal_creates 立账可忽略，#45）"
            )
    return warns

def apply_petition_event_outcome(
    state: GameState,
    db: GameDB,
    event_id: str,
    raw_label: object,
    *,
    commit: bool = True,
) -> Dict[str, object]:
    """亲裁语义落账的**单一写口**：把转译出的结局标签置成事件终态（#1892 / ADR 0153:5）。

    契约：

    - **事件须在可呈窗口内**：三饷只有到点才上疏（issues._event_window_open），窗口外
      的事项没有可供皇帝亲裁的既成事实，此时置定结局等于替皇帝凭空批一疏。窗口外
      响亮拒绝，不静默放过。
    - 标签只在事件自身声明的封闭集 ``terminal_reason_labels`` 内归一；归一不了就
      :class:`SettlementAbort` 响亮失败（ADR 0014：绝不兜底写未支撑值），不猜、不兜。
    - **留中不写终态**：raw_label 为空即「本疏已答而事件未终」，调用方不得以任何形式
      把它塞进终局标签集——留中不是结局标签。
    - 已落其它终态（expired/avoided/obsolete）的事件不被翻成 triggered；终态不可逆。

    写口只此一处：批红链路不直接写 ``terminal_reason``，原始选项标签不得旁路代批。
    """
    eid = str(event_id or "").strip()
    event = _fiscal_levy_event_by_id(eid) if eid else None
    if event is None:
        raise SettlementAbort(
            f"亲裁结局事件不存在：{eid}", turn=int(state.turn), stage="fiscal_levy_config",
        )
    if not _event_window_open(event, state):
        raise SettlementAbort(
            f"亲裁结局事件不在可呈窗口内：{eid}", turn=int(state.turn), stage="fiscal_levy_config",
        )
    raw = str(raw_label or "").strip()
    if not raw:
        # 留中：本疏已答，事件未终。不写终态，也不另开一条留中账。
        # 已呈原文与原批语在 record_event_petition_answer 的 choice_json 里。
        return {"id": eid, "settled": False, "terminal_state": "", "terminal_reason": ""}
    existing = db.event_terminal_state(eid)
    if existing == "triggered":
        # 一事件一裁断（ADR 0115:3 first-wins）：结局已落定即不可翻。
        return {
            "id": eid, "settled": False, "terminal_state": "triggered",
            "terminal_reason": _event_terminal_records(db).get(eid, {}).get("terminal_reason", ""),
        }
    if existing:
        return {
            "id": eid, "settled": False, "terminal_state": existing,
            "terminal_reason": _event_terminal_records(db).get(eid, {}).get("terminal_reason", ""),
        }
    label = _fiscal_levy_normalized_terminal_reason_or_abort(event, raw, state)
    # 所有权必须在写入前看。sqlite 对 DML 隐式 BEGIN，写完后再看 in_transaction
    # 永远为真，默认 commit=True 的独立调用就会报成功却不落盘。
    owns_transaction = commit and connection_owns_transaction(db.conn)
    db.mark_event_triggered(
        state, eid, source="petition_verdict", terminal_reason=label, commit=False,
    )
    apply_event_cascading_invalidations(state, db, commit=False)
    if owns_transaction:
        db.conn.commit()
    return {
        "id": eid, "settled": True, "terminal_state": "triggered", "terminal_reason": label,
    }

def normalize_travel_tone(value: object) -> str:
    """Validate the canonical typed travel tone; never infer or downgrade it."""
    tone = "常行" if value is None else str(value).strip()
    if tone not in TRAVEL_SPEED_BY_TONE:
        raise ValueError("行程语气不在闭合枚举")
    return tone

def normalize_reasoning_strength(value: object) -> str:
    strength = str(value or "").strip().lower()
    return strength if strength in {"off", "low", "medium", "high"} else ""

def _run_output_status_is_error(run_output: object) -> bool:
    """agno Agent.run 失败时 status=RunStatus.error（值 'ERROR'），content=str(exc)。

    #1299/#1310：此 status 是 runner/provider 失败的权威信号；不得把 content 当叙事放行。
    """
    status = getattr(run_output, "status", None)
    if status is None:
        return False
    raw = getattr(status, "value", status)
    return str(raw).strip().upper() in {"ERROR", "FAILED"}

def region_aliases(region: Region) -> List[str]:
    aliases = [region.id, region.name, compact_name(region.name)]
    for part in re.split(r"\s*/\s*|\s*／\s*", region.name):
        if part.strip():
            aliases.append(part.strip())
    aliases.extend(REGION_SPECIAL_ALIASES.get(region.id, ()))
    unique: List[str] = []
    seen: set = set()
    for alias in aliases:
        key = compact_name(alias)
        if not key or key in seen:
            continue
        seen.add(key)
        unique.append(alias)
    return unique

def _scene_opening_text(
    state: Any,
    present_rows: Sequence[tuple[str, str]],
    spoken: str,
    handling_by_person: Sequence[tuple[str, Sequence[tuple[str, str]]]],
    pending_audience_facts: Sequence[str] = (),
) -> str:
    """场景 LLM 开场最小集（ADR 0155）：在场、日期、正经手、本场已说、当前待裁场面。"""
    if present_rows:
        present_line = "、".join(
            f"{name}（{office}）" if office else name for name, office in present_rows
        )
    else:
        present_line = "（尚无）"
    parts = [
        f"在场：{present_line}",
        f"日期：{int(state.year)}年{int(state.period)}月",
    ]
    # 各在场人正经手事务（名字 + 当前情况一句）；无人经手则标（无）。
    parts.append("正经手事务：")
    any_handling = False
    for name, affairs in handling_by_person:
        if not affairs:
            continue
        any_handling = True
        parts.append(f"{name}：")
        parts.extend(f"- {title}：{situation}" for title, situation in affairs)
    if not any_handling:
        parts.append("（无）")
    parts.append("本场已说的话：")
    parts.append(spoken if spoken.strip() else "（尚无）")
    # #1838 reopen / ADR 0155：当前待裁场面（到期复命、暗渠摊派暴露/缺口重开）
    parts.append("当前待裁场面：")
    if pending_audience_facts:
        parts.extend(str(line) for line in pending_audience_facts)
    else:
        parts.append("（无）")
    parts.append(
        "在场诸人各自材料在 人物/<名>/ 下（人物档料、经历、公事档案、朝臣名册、事务、公开说法）。"
        "根目录 INDEX 一行一项。其余想读自己读。"
    )
    return "\n".join(parts)

def current_root() -> Path:
    value = root() if callable(root) else root
    text = str(value or "").strip()
    if not text:
        # Empty/cleared MaterialsRoot must not resolve Path("") → CWD.
        raise ValueError("材料目录未就绪")
    return Path(text)

def _person_effect_has_work(raw: object) -> bool:
    if not isinstance(raw, list):
        return False
    for item in raw:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name") or item.get("人物") or "").strip()
        action = str(item.get("动作") or item.get("action") or "").strip()
        if not name or action not in PERSON_ACTIONS:
            continue
        if action == "评定":
            loyalty = item.get("loyalty")
            if (
                not isinstance(loyalty, bool)
                and isinstance(loyalty, int)
                and loyalty != 0
            ):
                return True
            continue
        if action == "性情":
            style = item.get("style")
            if isinstance(style, str) and style.strip():
                return True
            continue
        return True
    return False

def _decree_ref_is_secret(db: Any, decree_ref: str) -> bool:
    from ming_sim.materials import is_secret_order_origin

    if is_secret_order_origin(decree_ref):
        return True
    prefix = "pending-action:"
    if not str(decree_ref).startswith(prefix):
        return False
    raw = str(decree_ref)[len(prefix):].split(":", 1)[0]
    if not raw.isdigit() or not hasattr(db, "conn"):
        return False
    row = db.conn.execute(
        "SELECT kind FROM pending_actions WHERE id=?", (int(raw),),
    ).fetchone()
    return row is not None and str(row["kind"] or "") == "secret_order"

def is_non_person_participant_name(name: str) -> bool:
